from lib import *
S = SS('t4')
steps = [
    step("先看没有故障时的代价。这是离散事件模拟(每条消息单程 5 ms,处理时间不计,每次写日志算一次强制落盘),不是真实网络。2PC:12 条消息(含确认)、7 次强制落盘,从协调者开始到最后一个参与者提交 15 ms = 3 个单程延迟。3PC:多了 PRECOMMIT 这一轮,18 条消息、10 次强制落盘、25 ms = 5 个单程延迟。3PC 比 2PC 多 6 条消息、多 3 次落盘、多 10 ms(多一个往返)。", t=tl(S(1)), mark=lidx(S(1), '3PC:18 条消息'), done=lidx(S(1), '2PC:12 条消息', '3PC 比 2PC 多'), b=bars([['2PC 消息数', 12, '12'], ['3PC 消息数', 18, '18'], ['2PC 强制落盘', 7, '7'], ['3PC 强制落盘', 10, '10'], ['2PC 耗时 ms', 15, '15'], ['3PC 耗时 ms', 25, '25']], 25, cur=[0, 2, 4], mark=[1, 3, 5]), kv=KV([['消息', '12 → 18'], ['强制落盘', '7 → 10'], ['延迟', '15 ms → 25 ms(多一个往返)']], ['延迟'])),
    step("协调者在每个位置崩溃、没有网络分区,剩下的参与者按终止协议自己收尾。2PC:协调者发出消息的 7 个崩溃点里,只有崩溃点 3(三个人都投了 YES、都不知道决定)是 BLOCKED——全部 READY,既不能提交也不能回滚;其余要么有人还没投票(INIT)可以单方面 ABORT,要么已经有人 COMMIT。3PC:10 个崩溃点没有一个阻塞——没人收到 PRECOMMIT 就 ABORT,有人收到就 COMMIT,崩溃点 3 全是 READY 也能直接 ABORT。这就是 3PC 想解决的问题:消除阻塞。", t=tl(S(2)), mark=lidx(S(2), '崩溃点  3(已发 PREPARE 给 P3)'), done=lidx(S(2), '没有分区时'), b=bars([['2PC 阻塞的崩溃点', 1, '1 / 7'], ['3PC 阻塞的崩溃点', 0, '0 / 10']], 1, mark=[0], done=[1]), kv=KV([['2PC', '全部 READY 的窗口里阻塞'], ['3PC', '多一轮 PRECOMMIT,READY 可以安全 ABORT'], ['前提', '没有网络分区']], ['前提'])),
    step("叠加网络分区(协调者挂掉的同时,参与者被切成连不通的小组,每个小组各自跑终止协议),把崩溃点和 5 种分区方式全部枚举。2PC:35 个场景里 18 个正常收尾、17 个阻塞、0 个结果不一致——它宁可阻塞。3PC:50 个场景里 44 个正常收尾、0 个阻塞、6 个结果不一致:协调者只给 P1(或 P1、P2)发了 PRECOMMIT 就挂,有 PRECOMMIT 的小组 COMMIT,没有的小组 ABORT。3PC 用“不阻塞”换来了“分区时可能出现两种结局”。", t=tl(S(3)), mark=lidx(S(3), '3PC:50 个场景', '崩溃点  4(已发 PRECOMMIT 给 P1)  分区 P1|P2P3'), done=lidx(S(3), '2PC:35 个场景', '2PC 在分区下'), b=bars([['2PC 阻塞', 17, '17'], ['2PC 不一致', 0, '0'], ['3PC 阻塞', 0, '0'], ['3PC 不一致', 6, '6']], 17, cur=[0], mark=[3], done=[1, 2]), kv=KV([['2PC', '17 阻塞、0 不一致'], ['3PC', '0 阻塞、6 不一致'], ['取舍', '2PC 保一致丢可用,3PC 反过来']], ['取舍'])),
    step("看其中一个具体的 3PC 不一致过程:协调者只把 PRECOMMIT 发给了 P1 就挂了,P1 和 P2、P3 被分在两边。此刻状态 P1=PRECOMMIT、P2=READY、P3=READY。P1 这一组超时后按规则 COMMIT(有人收到 PRECOMMIT,说明所有人都投过 YES);P2、P3 这一组超时后 ABORT(没有人收到 PRECOMMIT,不可能有人已经提交)。两个小组的推理各自都对,合在一起 P1 提交、P2 和 P3 回滚,分区恢复后这笔事务的结局永远对不上。", t=tl(S(4)), mark=lidx(S(4), '小组 P1:超时', '小组 P2P3:超时'), done=lidx(S(4), 'P1 提交了'), kv=KV([['P1', 'PRECOMMIT → 超时 COMMIT'], ['P2、P3', 'READY → 超时 ABORT'], ['结果', 'P1 提交,P2/P3 回滚']], ['结果'])),
    step("同样的场景换成 2PC:协调者只把 COMMIT 发给了 P1 就挂了,P1 和 P2、P3 分在两边。P1=COMMIT 已经提交;P2、P3 都是 READY,小组里没有人知道决定,终止协议给出 BLOCKED——不敢动,等分区恢复后向 P1 打听到 COMMIT 再提交。代价是这段时间它们的锁一直握着,但结局是对的。这就是 2PC 与 3PC 的取舍:2PC 在不确定时等待,3PC 在不确定时猜,猜在分区时可能猜错。", t=tl(S(5)), mark=lidx(S(5), '小组 P2P3:BLOCKED'), done=lidx(S(5), '小组 P1:COMMIT', 'P1 已经提交'), kv=KV([['P1', '已 COMMIT'], ['P2、P3', 'BLOCKED,等分区恢复'], ['代价', '锁一直握着,但结局对']], ['代价'])),
]
A = mkartt('t4', 4, '分布式事务,三阶段提交,3PC,2PC,协议建模,枚举,动画演示',
    '用协议模型穷举实测 3PC 为什么很少用:没有分区时 2PC 在 7 个崩溃点里有 1 个阻塞、3PC 的 10 个都不阻塞;叠加网络分区后 2PC 的 35 个场景 17 个阻塞、0 个不一致,3PC 的 50 个场景 0 个阻塞、6 个不一致;3PC 还多 6 条消息、多一个往返。',
    '三阶段提交在 2PC 上加了一轮 PRECOMMIT,目标是消除阻塞。它真的更好吗?这篇把两个协议写成状态模型,枚举协调者的每个崩溃位置和每种网络分区,数出两者各自的阻塞和不一致,再算出多出来的消息和延迟。',
    [('6 / 50', '3PC 在崩溃点 × 分区的 50 个场景里,各小组做出相反决定的场景数(2PC 是 0 / 35)'), ('1 / 7 → 0 / 10', '没有分区时,2PC 与 3PC 会让参与者阻塞的协调者崩溃点'), ('+10 ms', '无故障时 3PC 比 2PC 多的延迟(模型里单程 5 ms,多一个往返)')],
    [('代价:多一轮', '<p>3PC 在投票和提交之间加了 PRECOMMIT 一轮:多 6 条消息、多 3 次强制落盘、多一个往返。</p>'),
     ('没有分区:3PC 确实不阻塞', '<p>2PC 在“全部 READY、没人知道决定”的窗口里阻塞;3PC 因为 READY 状态下一定没人提交,可以安全 ABORT,枚举下来没有一个阻塞的崩溃点。</p>'),
     ('有分区:阻塞换成了不一致', '<p>3PC 的“超时就决定”假设了超时一定是崩溃而不是分区。分区时两个小组各按规则收尾,会做出相反的决定;2PC 在同样的场景里只是阻塞。</p>'),
     ('一个具体的不一致', '<p>PRECOMMIT 只发出去一个就挂,有 PRECOMMIT 的一方提交,其余回滚。两边各自的推理都符合协议。</p>'),
     ('2PC 的取舍', '<p>2PC 在不确定时等,3PC 在不确定时猜。真实系统不靠 3PC 解决 2PC 的阻塞,而是让协调者本身不再单点(比如把协调者的状态放进共识组),这一点本篇没有验证。</p>')],
    steps,
    [ENV_T + '。本篇没有用任何数据库:2PC 和 3PC 是我按教科书规则写的状态模型(tools/articles/exp/t4.py),消息、延迟和强制落盘数来自离散事件模拟(单程延迟取 5 ms),不一致 / 阻塞来自对协调者崩溃点 × 网络分区方式的穷举;3 个参与者、全部投 YES 的情形',
     '没有验证:任何真实的 3PC 实现(没有主流数据库实现它);参与者也崩溃、投 NO、多次崩溃的组合;带时钟同步假设的 3PC 变体;把协调者放进 Paxos / Raft 组之后的 2PC(业界常见做法,本篇没有实验);超时参数和真实网络的行为'],
    '2PC 与 3PC')
